namespace Core;require_once __DIR__.'/Guard.php';ml_guard_shield(__FILE__);require_once __DIR__.'/Config.php';class Mail{private static $lastLog='';public static function cfg(){return array('enable'=>self::flag(Config::sub('mail','enable',0)),'host'=>trim((string)Config::sub('mail','host','')),'port'=>(int)Config::sub('mail','port',465),'secure'=>strtolower(trim((string)Config::sub('mail','secure','ssl'))),'user'=>trim((string)Config::sub('mail','user','')),'pass'=>(string)Config::sub('mail','pass',''),'from'=>trim((string)Config::sub('mail','from','')),'from_name'=>trim((string)Config::sub('mail','from_name','')),'timeout'=>max(5,(int)Config::sub('mail','timeout',15)),);}private static function flag($a){if(is_bool($a)){return $a;}$b=strtolower(trim((string)$a));return in_array($b,array('1','on','true','yes','y'),true);}public static function ready(){$a=self::cfg();return($a['enable']&&$a['host']!==''&&$a['user']!==''&&$a['pass']!==''&&$a['from']!=='');}public static function whyNotReady(){return self::whyNotReadyOf(self::cfg());}private static function whyNotReadyOf($a){if(!$a['enable']){return'邮件服务未启用（请到「站点设置 → 邮件服务」打开开关）。';}if($a['host']===''){return'还没填 SMTP 服务器地址。';}if($a['user']===''){return'还没填 SMTP 账号。';}if($a['pass']===''){return'还没填 SMTP 密码 / 授权码。';}if($a['from']===''){return'还没填发件人邮箱。';}return'';}public static function lastLog(){return self::$lastLog;}public static function send($a,$b,$c,$d='',$e=null){$f=self::cfg();if(is_array($e)){foreach($e as $g=>$h){if($h===null||$h===''){continue;}$f[$g]=$h;}$f['port']=(int)$f['port'];$f['enable']=self::flag($f['enable']);}$i=self::whyNotReadyOf($f);if($i!==''){self::$lastLog=$i;return array('ok'=>false,'msg'=>$i);}$a=trim((string)$a);if($a===''||!filter_var($a,FILTER_VALIDATE_EMAIL)){self::$lastLog='收件邮箱不合法：'.$a;return array('ok'=>false,'msg'=>'收件邮箱不合法。');}if($d===''){$d=trim(strip_tags(str_replace(array('<br>','<br/>','<br />','</p>'),"\n",(string)$c)));}$j=($f['from_name']!=='')?$f['from_name']:$f['from'];$k=sel